fn frame(t: i32) {
    let mut bins = [0; 8];
    let mut h: i32 = 7;
    let mut i: i32 = 0;
    while i < 64 {
        h = h * 1103515245 + 12345;
        let idx: i32 = (h >> 16) & 7;
        bins[idx] = bins[idx] + 1;
        i = i + 1;
    }
    let w: i32 = host::display::width();
    let hh: i32 = host::display::height();
    host::display::clear(0x000000);
    let bw: i32 = w / 8;
    let mut k: i32 = 0;
    while k < 8 {
        host::display::fill_rect(k * bw + 2, hh - bins[k] * 8 - 4, bw - 4, bins[k] * 8, 0xffaa00);
        k = k + 1;
    }
    host::display::present();
}
